class Solution {
    public int countSymmetricIntegers(int low, int high) {
        int count = 0;
        for (int value = low; value <= high; value++) {
            String digits = Integer.toString(value);
            if ((digits.length() & 1) == 1) {
                continue;
            }
            int half = digits.length() / 2;
            int leftSum = 0;
            int rightSum = 0;
            for (int i = 0; i < half; i++) {
                leftSum += digits.charAt(i) - '0';
                rightSum += digits.charAt(i + half) - '0';
            }
            if (leftSum == rightSum) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int countSymmetricIntegers(int low, int high) {
        int count = 0;
        for (int value = low; value <= high; value++) {
            if (isSymmetric(value)) {
                count++;
            }
        }
        return count;
    }

    private boolean isSymmetric(int value) {
        int digits = 0;
        for (int x = value; x > 0; x /= 10) {
            digits++;
        }
        if ((digits & 1) == 1) {
            return false;
        }
        int half = digits / 2;
        int remaining = value;
        int rightSum = 0;
        for (int i = 0; i < half; i++) {
            rightSum += remaining % 10;
            remaining /= 10;
        }
        int leftSum = 0;
        while (remaining > 0) {
            leftSum += remaining % 10;
            remaining /= 10;
        }
        return leftSum == rightSum;
    }
}

class Solution {
    public int countSymmetricIntegers(int low, int high) {
        int count = 0;
        for (int value = low; value <= high; value++) {
            if (value >= 10 && value <= 99) {
                int tens = value / 10;
                int ones = value % 10;
                if (tens == ones) {
                    count++;
                }
            } else if (value >= 1000 && value <= 9999) {
                int firstHalf = value / 1000 + (value / 100) % 10;
                int secondHalf = (value / 10) % 10 + value % 10;
                if (firstHalf == secondHalf) {
                    count++;
                }
            }
        }
        return count;
    }
}

class Solution {
    public int countSymmetricIntegers(int low, int high) {
        int[] prefix = new int[high + 1];
        for (int value = 1; value <= high; value++) {
            prefix[value] = prefix[value - 1] + (isSymmetric(value) ? 1 : 0);
        }
        return prefix[high] - prefix[low - 1];
    }

    private boolean isSymmetric(int value) {
        String digits = Integer.toString(value);
        if ((digits.length() & 1) == 1) {
            return false;
        }
        int half = digits.length() / 2;
        int balance = 0;
        for (int i = 0; i < digits.length(); i++) {
            int digit = digits.charAt(i) - '0';
            if (i < half) {
                balance += digit;
            } else {
                balance -= digit;
            }
        }
        return balance == 0;
    }
}
